using System.Numerics;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;

namespace MinMax;

public static class RangeCalculator
{
    /// <summary>
    /// Returns the minimum and maximum values in <paramref name="values"/>.
    /// Uses SIMD vectorization for maximum throughput on large spans.
    /// </summary>
    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    public static (float Min, float Max) FindMinMax(ReadOnlySpan<float> values)
    {
        if (values.Length == 0)
            throw new ArgumentException("Span must not be empty.");

        if (!Vector.IsHardwareAccelerated || values.Length < Vector<float>.Count * 2)
        {
            return FindMinMaxScalar(values);
        }

        ref float searchSpace = ref MemoryMarshal.GetReference(values);
        int vectorCount = Vector<float>.Count;
        int lastVectorStart = values.Length - (values.Length % vectorCount);

        var vMin = new Vector<float>(values[0]);
        var vMax = vMin;

        int i = 0;
        // Process two vectors per iteration to improve instruction-level parallelism
        int lastDoubleVectorStart = lastVectorStart - vectorCount;
        for (; i <= lastDoubleVectorStart; i += vectorCount * 2)
        {
            var current1 = new Vector<float>(values.Slice(i, vectorCount));
            var current2 = new Vector<float>(values.Slice(i + vectorCount, vectorCount));
            vMin = Vector.Min(vMin, Vector.Min(current1, current2));
            vMax = Vector.Max(vMax, Vector.Max(current1, current2));
        }

        // Handle remaining full vector
        for (; i < lastVectorStart; i += vectorCount)
        {
            var current = new Vector<float>(values.Slice(i, vectorCount));
            vMin = Vector.Min(vMin, current);
            vMax = Vector.Max(vMax, current);
        }

        // Reduce vectors to scalar
        float min = vMin[0];
        float max = vMax[0];
        for (int j = 1; j < vectorCount; j++)
        {
            if (vMin[j] < min) min = vMin[j];
            if (vMax[j] > max) max = vMax[j];
        }

        // Handle remaining elements
        for (; i < values.Length; i++)
        {
            float val = Unsafe.Add(ref searchSpace, i);
            if (val < min) min = val;
            if (val > max) max = val;
        }

        return (min, max);
    }

    private static (float Min, float Max) FindMinMaxScalar(ReadOnlySpan<float> values)
    {
        float min = values[0];
        float max = values[0];
        for (int i = 1; i < values.Length; i++)
        {
            if (values[i] < min) min = values[i];
            if (values[i] > max) max = values[i];
        }
        return (min, max);
    }
}

